def transform(grid):
    h, w = len(grid), len(grid[0])

    # Separator rows/columns are the repeated lines containing the background
    # color, while the spaces between them are uniform tile interiors.
    def line_candidates(axis):
        n = h if axis == 0 else w
        other = w if axis == 0 else h
        lines = []
        for i in range(n):
            vals = [grid[i][j] if axis == 0 else grid[j][i] for j in range(other)]
            if len(set(vals)) > 1:
                lines.append(i)
        return lines

    rlines = line_candidates(0)
    clines = line_candidates(1)

    def common_step(lines):
        ds = [b-a for a, b in zip(lines, lines[1:])]
        if not ds:
            return 1
        return max(set(ds), key=ds.count)

    rs, cs = common_step(rlines), common_step(clines)
    # Grid lines occur at a fixed phase; find that phase by the strongest
    # concentration of non-interior marks.
    def phase(lines, step):
        return min(range(step), key=lambda p: -sum(1 for x in lines if x % step == p))
    rp, cp = phase(rlines, rs), phase(clines, cs)

    rmarks = list(range(rp, h, rs))
    cmarks = list(range(cp, w, cs))
    nr = max(1, len(rmarks)-1)
    nc = max(1, len(cmarks)-1)

    # Tile fill color is the most frequent value overall.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    fill = max(counts, key=counts.get)
    out = [[fill for _ in range(nc)] for _ in range(nr)]

    for ri, r in enumerate(rmarks):
        for ci, c in enumerate(cmarks):
            v = grid[r][c]
            if v != fill:
                out[min(ri, nr-1)][min(ci, nc-1)] = v
    return out
