def transform(grid):
    h, w = len(grid), len(grid[0])

    def separator_indices(horizontal):
        n = h if horizontal else w
        m = w if horizontal else h
        return [
            i for i in range(n)
            if len({grid[i][j] if horizontal else grid[j][i] for j in range(m)}) > 1
        ]

    def infer(lines, limit):
        # Find the regular spacing and phase that best match the separator lines.
        best = None
        for step in range(2, limit + 1):
            for phase in range(step):
                score = sum(i % step == phase for i in lines)
                if best is None or score > best[0]:
                    best = (score, step, phase)
        _, step, phase = best
        return list(range(phase, limit, step))

    rows = infer(separator_indices(True), h)
    cols = infer(separator_indices(False), w)

    # Every adjacent pair of separator lines frames one output cell. The
    # marker at the upper-left lattice intersection supplies its color.
    nr, nc = len(rows) - 1, len(cols) - 1
    lattice = [[grid[r][c] for c in cols[:-1]] for r in rows[:-1]]

    # Most lattice intersections are the separator's ordinary background.
    vals = [v for row in lattice for v in row]
    background = max(set(vals), key=vals.count)
    interior = {}
    for row in grid:
        for v in row:
            interior[v] = interior.get(v, 0) + 1
    fill = max(interior, key=interior.get)

    return [[fill if v == background else v for v in row] for row in lattice]
