def transform(grid):
    h, w = len(grid), len(grid[0])

    # Identify the regularly spaced separator lines by looking for rows and
    # columns whose predominant color is the frame color rather than the tile fill.
    def candidate_lines(horizontal):
        n = h if horizontal else w
        m = w if horizontal else h
        lines = []
        for i in range(n):
            vals = [grid[i][j] if horizontal else grid[j][i] for j in range(m)]
            counts = {}
            for v in vals:
                counts[v] = counts.get(v, 0) + 1
            if max(counts.values()) >= m * 0.55:
                lines.append(i)
        return lines

    def lattice(lines, n):
        # Select the most frequent positive interval between candidate lines.
        gaps = [b - a for a, b in zip(lines, lines[1:])]
        step = max(set(gaps), key=gaps.count)
        phase = max(range(step), key=lambda p: sum(x % step == p for x in lines))
        return list(range(phase, n, step))

    rows = lattice(candidate_lines(True), h)
    cols = lattice(candidate_lines(False), w)
    nr, nc = len(rows) - 1, len(cols) - 1

    # The predominant interior color is the value for unmarked output cells.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    fill = max(counts, key=counts.get)

    # The common frame color at the lattice intersections is the neutral mark.
    vals = [grid[r][c] for r in rows[:-1] for c in cols[:-1]]
    neutral = max(set(vals), key=vals.count)

    return [
        [grid[r][c] if grid[r][c] != neutral else fill for c in cols[:-1]]
        for r in rows[:-1]
    ]
